<?php
declare(strict_types=1);
namespace Architex\Platform\Environment;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Project\ProjectContext;
use Architex\Platform\Project\ProjectPhase;
use Architex\Platform\Records\ProjectRecordService;
use DateTimeImmutable;
use PDO;
use PDOException;
use Throwable;

final readonly class RegulatoryCaseService
{
    private const TYPES=['environmental','heritage'];
    private const EVIDENCE=['screening_report','site_sensitivity_verification','listed_activity_review','specialist_study','public_participation','empr','monitoring','audit','heritage_nid','heritage_impact_assessment','authority_correspondence','permit','condition'];
    private const STATUSES=['draft','pending','complete','submitted_externally','received','accepted','rejected','closed'];
    private const ROUTES=['no_ea_indicated','basic_assessment','scoping_eia','nid','heritage_impact_assessment','permit_required','other'];
    public function __construct(private PDO$pdo){}
    /** @return list<array<string,mixed>> */public function list(string$o,string$u,string$p,?string$type=null):array{$this->member($o,$u);$p=$this->id($p,'regulatory_project_not_found');$this->project($o,$p);$params=['o'=>$o,'p'=>$p];$where='organisation_id=UNHEX(:o) AND project_id=UNHEX(:p)';if($type!==null){$type=$this->choice($type,self::TYPES,'regulatory_case_type_invalid');$where.=' AND case_type=:type';$params['type']=$type;}$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) FROM regulatory_cases WHERE $where ORDER BY created_at DESC,id DESC");$s->execute($params);$out=[];foreach($s->fetchAll(PDO::FETCH_COLUMN)as$id)$out[]=$this->get($o,$u,(string)$id);return$out;}
    /** @param array<string,mixed>$i @return array<string,mixed> */public function create(string$o,string$u,string$r,array$i):array{$this->writer($o,$u,$r);$p=$this->id($i['projectId']??null,'regulatory_project_not_found');$this->project($o,$p);$type=$this->choice($i['caseType']??null,self::TYPES,'regulatory_case_type_invalid');$sources=$this->sources($i['sourceBasis']??null);$id=Identifier::generate();$v=['id'=>$id,'o'=>$o,'p'=>$p,'number'=>$this->text($i['caseNumber']??null,80,'regulatory_case_number_required'),'type'=>$type,'title'=>$this->text($i['title']??null,220,'regulatory_title_required'),'authority'=>$this->text($i['authorityName']??null,220,'regulatory_authority_required'),'role'=>$this->role($i['responsibleRole']??null),'sources'=>$this->json($sources),'u'=>$u];try{$this->pdo->beginTransaction();$this->pdo->prepare('INSERT INTO regulatory_cases(id,organisation_id,project_id,case_number,case_type,title,authority_name,responsible_role,source_basis,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),:number,:type,:title,:authority,:role,:sources,UNHEX(:u))')->execute($v);(new AuditService($this->pdo))->append($o,$u,'regulatory.case.created','regulatory_case',$id,['projectId'=>$p,'caseType'=>$type,'caseNumber'=>$v['number'],'sourceBasis'=>$sources,'authorityDecisionClaimed'=>false]);$this->pdo->commit();}catch(PDOException$e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((string)$e->getCode()==='23000')throw new RegulatoryCaseException('regulatory_case_number_exists');throw$e;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->get($o,$u,$id);}
    /** @param array<string,mixed>$i @return array<string,mixed> */public function addEvidence(string$o,string$u,string$r,string$id,int$expected,array$i):array{$this->writer($o,$u,$r);$case=$this->draft($o,$u,$id,$expected);$eid=Identifier::generate();$payload=$i['payload']??null;if(!is_array($payload))throw new RegulatoryCaseException('regulatory_evidence_payload_invalid');$v=['id'=>$eid,'o'=>$o,'p'=>$case['projectId'],'case'=>$id,'type'=>$this->choice($i['evidenceType']??null,self::EVIDENCE,'regulatory_evidence_type_invalid'),'title'=>$this->text($i['title']??null,220,'regulatory_evidence_title_required'),'status'=>$this->choice($i['status']??null,self::STATUSES,'regulatory_evidence_status_invalid'),'ref'=>$this->text($i['externalReference']??null,180,'regulatory_evidence_reference_required'),'url'=>$this->url($i['sourceUrl']??null),'date'=>$this->date($i['observedAt']??null),'payload'=>$this->json($payload),'u'=>$u];try{$this->pdo->beginTransaction();$this->lock($o,$id,$expected);$this->pdo->prepare('INSERT INTO regulatory_case_evidence(id,organisation_id,project_id,case_id,evidence_type,title,status,external_reference,source_url,observed_on,payload,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:p),UNHEX(:case),:type,:title,:status,:ref,:url,:date,:payload,UNHEX(:u))')->execute($v);$this->bump($o,$id,$expected);(new AuditService($this->pdo))->append($o,$u,'regulatory.evidence.created','regulatory_case_evidence',$eid,['caseId'=>$id,'evidenceType'=>$v['type'],'externalReference'=>$v['ref'],'sourceUrl'=>$v['url']]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}$e=$this->evidence($o,$eid);$e['caseVersion']=$expected+1;return$e;}
    /** @return array<string,mixed> */public function determine(string$o,string$u,string$r,string$id,int$expected,bool$confirmed,string$role,string$route,string$reason,string$reference):array{$this->writer($o,$u,$r);if(!$confirmed)throw new RegulatoryCaseException('regulatory_determination_confirmation_required');$role=$this->role($role);$route=$this->choice($route,self::ROUTES,'regulatory_determination_route_invalid');$reason=$this->text($reason,500,'regulatory_determination_reason_required');$reference=$this->text($reference,180,'regulatory_determination_reference_required');$case=$this->draft($o,$u,$id,$expected);if($role!==$case['responsibleRole']||!$this->canActAs($o,$u,$case['projectId'],$role))throw new RegulatoryCaseException('regulatory_determination_role_denied');$types=array_column($case['evidence'],'evidenceType');$required=$case['caseType']==='environmental'?['screening_report','site_sensitivity_verification']:['heritage_nid','heritage_impact_assessment'];if(array_diff($required,$types)!==[])throw new RegulatoryCaseException('regulatory_determination_evidence_incomplete');$snapshot=['case'=>array_intersect_key($case,array_flip(['id','projectId','caseNumber','caseType','title','authorityName','responsibleRole','sourceBasis'])),'evidence'=>$case['evidence'],'determination'=>['route'=>$route,'externalReference'=>$reference,'reason'=>$reason,'professionalRole'=>$role,'humanConfirmed'=>true,'authorityDecisionClaimed'=>false,'authorisationClaimed'=>false]];$json=$this->json($snapshot);$sha=hash('sha256',$json);$project=$this->project($o,$case['projectId']);try{$this->pdo->beginTransaction();$this->lock($o,$id,$expected);$record=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($o,$u,$case['projectId'],$r),ProjectPhase::from($project['currentPhase']),'environmental_heritage','regulatory_determination',$case['caseNumber'].' '.$case['title'],'issued',['caseId'=>$id,'caseType'=>$case['caseType'],'route'=>$route,'snapshotSha256'=>$sha,'authorityDecisionClaimed'=>false],['required'=>true,'humanApprovalConfirmed'=>true,'approvedBy'=>$u,'professionalRole'=>$role,'reason'=>$reason]);$s=$this->pdo->prepare("UPDATE regulatory_cases SET status='determined',version=version+1,determination_route=:route,external_reference=:ref,determination_reason=:reason,snapshot_payload=:snapshot,snapshot_sha256=:sha,project_record_id=UNHEX(:record),determined_by=UNHEX(:u),determined_at=UTC_TIMESTAMP(6) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND version=:version AND status='draft'");$s->execute(['route'=>$route,'ref'=>$reference,'reason'=>$reason,'snapshot'=>$json,'sha'=>$sha,'record'=>$record,'u'=>$u,'id'=>$id,'o'=>$o,'version'=>$expected]);if($s->rowCount()!==1)throw new RegulatoryCaseException('regulatory_version_conflict');(new AuditService($this->pdo))->append($o,$u,'regulatory.case.determined','regulatory_case',$id,['route'=>$route,'externalReference'=>$reference,'snapshotSha256'=>$sha,'projectRecordId'=>$record,'authorityDecisionClaimed'=>false]);$this->pdo->commit();}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}return$this->get($o,$u,$id);}
    /** @return array<string,mixed> */public function get(string$o,string$u,string$id):array{$this->member($o,$u);$id=$this->id($id,'regulatory_case_not_found');$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,LOWER(HEX(project_id)) project_id,case_number,case_type,title,authority_name,responsible_role,source_basis,status,version,determination_route,external_reference,determination_reason,snapshot_payload,snapshot_sha256,LOWER(HEX(project_record_id)) project_record_id,determined_at,created_at FROM regulatory_cases WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)");$s->execute(['id'=>$id,'o'=>$o]);$r=$s->fetch();if(!is_array($r))throw new RegulatoryCaseException('regulatory_case_not_found');$snapshot=$r['snapshot_payload']===null?null:json_decode((string)$r['snapshot_payload'],true,64,JSON_THROW_ON_ERROR);if($snapshot!==null&&!hash_equals((string)$r['snapshot_sha256'],hash('sha256',$this->json($snapshot))))throw new RegulatoryCaseException('regulatory_integrity_failed');return['id'=>$r['id'],'projectId'=>$r['project_id'],'caseNumber'=>$r['case_number'],'caseType'=>$r['case_type'],'title'=>$r['title'],'authorityName'=>$r['authority_name'],'responsibleRole'=>$r['responsible_role'],'sourceBasis'=>json_decode((string)$r['source_basis'],true,64,JSON_THROW_ON_ERROR),'status'=>$r['status'],'version'=>(int)$r['version'],'determinationRoute'=>$r['determination_route'],'externalReference'=>$r['external_reference'],'determinationReason'=>$r['determination_reason'],'snapshot'=>$snapshot,'snapshotSha256'=>$r['snapshot_sha256'],'projectRecordId'=>$r['project_record_id'],'determinedAt'=>$r['determined_at'],'createdAt'=>$r['created_at'],'evidence'=>$this->evidences($o,$id),'authorityDecisionClaimed'=>false,'authorisationClaimed'=>false];}
    /** @return array{filename:string,mimeType:string,content:string,sha256:string} */public function export(string$o,string$u,string$id,string$format):array{$case=$this->get($o,$u,$id);$base=preg_replace('/[^A-Za-z0-9._-]+/','-',strtolower($case['caseNumber']))?:'regulatory-case';if($format==='json'){$content=json_encode($case,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$mime='application/json';}elseif($format==='csv'){$stream=fopen('php://temp','w+b');fputcsv($stream,['case_number','case_type','status','determination_route','evidence_type','evidence_status','title','external_reference','source_url','observed_on']);foreach($case['evidence']as$e)fputcsv($stream,[$case['caseNumber'],$case['caseType'],$case['status'],$case['determinationRoute'],$e['evidenceType'],$e['status'],$e['title'],$e['externalReference'],$e['sourceUrl'],$e['observedAt']]);rewind($stream);$content=(string)stream_get_contents($stream);fclose($stream);$mime='text/csv';}elseif($format==='html'){$h=static fn(mixed$v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$rows='';foreach($case['evidence']as$e)$rows.='<tr><td>'.$h($e['evidenceType']).'</td><td>'.$h($e['status']).'</td><td>'.$h($e['title']).'</td><td>'.$h($e['externalReference']).'</td></tr>';$content='<!doctype html><html><meta charset="utf-8"><title>'.$h($case['caseNumber']).'</title><body><h1>'.$h($case['caseNumber']).' — '.$h($case['title']).'</h1><p>'.$h($case['caseType']).' · '.$h($case['status']).' · '.$h($case['determinationRoute']).'</p><p>Determination SHA-256: '.$h($case['snapshotSha256']).'</p><p>Authority decision claimed: no</p><table><thead><tr><th>Evidence</th><th>Status</th><th>Title</th><th>Reference</th></tr></thead><tbody>'.$rows.'</tbody></table></body></html>';$mime='text/html';}else throw new RegulatoryCaseException('regulatory_export_format_invalid');return['filename'=>$base.'.'.$format,'mimeType'=>$mime,'content'=>$content,'sha256'=>hash('sha256',$content)];}
    /** @return list<array<string,mixed>> */private function evidences(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,evidence_type,title,status,external_reference,source_url,observed_on,payload,LOWER(HEX(created_by)) created_by,created_at FROM regulatory_case_evidence WHERE organisation_id=UNHEX(:o) AND case_id=UNHEX(:id) ORDER BY created_at,id");$s->execute(['o'=>$o,'id'=>$id]);$out=[];foreach($s->fetchAll()as$r)$out[]=$this->mapEvidence($r);return$out;}
    /** @return array<string,mixed> */private function evidence(string$o,string$id):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(id)) id,evidence_type,title,status,external_reference,source_url,observed_on,payload,LOWER(HEX(created_by)) created_by,created_at FROM regulatory_case_evidence WHERE organisation_id=UNHEX(:o) AND id=UNHEX(:id)");$s->execute(['o'=>$o,'id'=>$id]);$r=$s->fetch();if(!is_array($r))throw new RegulatoryCaseException('regulatory_evidence_not_found');return$this->mapEvidence($r);}
    /** @param array<string,mixed>$r @return array<string,mixed> */private function mapEvidence(array$r):array{return['id'=>$r['id'],'evidenceType'=>$r['evidence_type'],'title'=>$r['title'],'status'=>$r['status'],'externalReference'=>$r['external_reference'],'sourceUrl'=>$r['source_url'],'observedAt'=>$r['observed_on'],'payload'=>json_decode((string)$r['payload'],true,64,JSON_THROW_ON_ERROR),'createdBy'=>$r['created_by'],'createdAt'=>$r['created_at']];}
    /** @return array<string,mixed> */private function draft(string$o,string$u,string$id,int$v):array{$c=$this->get($o,$u,$id);if($c['status']!=='draft')throw new RegulatoryCaseException('regulatory_case_determined');if($v<1||$c['version']!==$v)throw new RegulatoryCaseException('regulatory_version_conflict');return$c;}private function lock(string$o,string$id,int$v):void{$s=$this->pdo->prepare("SELECT version,status FROM regulatory_cases WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) FOR UPDATE");$s->execute(['id'=>$id,'o'=>$o]);$r=$s->fetch();if(!is_array($r))throw new RegulatoryCaseException('regulatory_case_not_found');if($r['status']!=='draft')throw new RegulatoryCaseException('regulatory_case_determined');if((int)$r['version']!==$v)throw new RegulatoryCaseException('regulatory_version_conflict');}private function bump(string$o,string$id,int$v):void{$s=$this->pdo->prepare("UPDATE regulatory_cases SET version=version+1 WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND version=:v AND status='draft'");$s->execute(['id'=>$id,'o'=>$o,'v'=>$v]);if($s->rowCount()!==1)throw new RegulatoryCaseException('regulatory_version_conflict');}
    /** @return array{currentPhase:string,leadProfessionalRole:string,createdBy:string} */private function project(string$o,string$p):array{$s=$this->pdo->prepare("SELECT current_phase currentPhase,lead_professional_role leadProfessionalRole,LOWER(HEX(created_by)) createdBy FROM projects WHERE id=UNHEX(:p) AND organisation_id=UNHEX(:o)");$s->execute(['p'=>$p,'o'=>$o]);$r=$s->fetch();if(!is_array($r))throw new RegulatoryCaseException('regulatory_project_not_found');return$r;}private function canActAs(string$o,string$u,string$p,string$r):bool{$project=$this->project($o,$p);$assigned=hash_equals($project['createdBy'],$u)&&$project['leadProfessionalRole']===$r;if(!$assigned){$s=$this->pdo->prepare("SELECT 1 FROM project_team_members WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND user_id=UNHEX(:u) AND status='active' AND discipline=:r AND verification_grade IN ('manually_reviewed','externally_verified')");$s->execute(['o'=>$o,'p'=>$p,'u'=>$u,'r'=>$r]);$assigned=$s->fetchColumn()!==false;}if(!$assigned)return false;$authority=$this->pdo->prepare("SELECT 1 FROM verification_records v JOIN professional_profiles p ON p.organisation_id=v.organisation_id AND p.user_id=v.user_id AND p.profession=:r WHERE v.organisation_id=UNHEX(:o) AND v.user_id=UNHEX(:u) AND v.kind='professional_registration' AND v.grade IN ('manually_reviewed','externally_verified') AND v.reviewed_by IS NOT NULL AND v.reviewed_by<>v.user_id AND (v.expires_on IS NULL OR v.expires_on>=UTC_DATE()) LIMIT 1");$authority->execute(['o'=>$o,'u'=>$u,'r'=>$r]);return$authority->fetchColumn()!==false;}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new RegulatoryCaseException('regulatory_permission_denied');$this->member($o,$u);}private function member(string$o,string$u):void{$this->id($o,'regulatory_permission_denied');$this->id($u,'regulatory_permission_denied');$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()===false)throw new RegulatoryCaseException('regulatory_permission_denied');}
    /** @return list<array{title:string,url:string,retrievedAt:string}> */private function sources(mixed$v):array{if(!is_array($v)||$v===[]||count($v)>20)throw new RegulatoryCaseException('regulatory_source_basis_required');$out=[];foreach($v as$s){if(!is_array($s))throw new RegulatoryCaseException('regulatory_source_basis_invalid');$out[]=['title'=>$this->text($s['title']??null,220,'regulatory_source_title_required'),'url'=>$this->url($s['url']??null),'retrievedAt'=>$this->date($s['retrievedAt']??null)];}return$out;}private function url(mixed$v):string{$v=$this->text($v,1000,'regulatory_source_url_required');if(filter_var($v,FILTER_VALIDATE_URL)===false||!in_array(parse_url($v,PHP_URL_SCHEME),['http','https'],true))throw new RegulatoryCaseException('regulatory_source_url_invalid');return$v;}private function date(mixed$v):string{$v=$this->text($v,10,'regulatory_source_date_required');$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new RegulatoryCaseException('regulatory_source_date_invalid');return$v;}
    private function id(mixed$v,string$e):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new RegulatoryCaseException($e);return strtolower($v);}private function role(mixed$v):string{$v=$this->text($v,80,'regulatory_role_invalid');if(preg_match('/\A[a-z][a-z0-9_]{1,79}\z/',$v)!==1)throw new RegulatoryCaseException('regulatory_role_invalid');return$v;}/** @param list<string>$a */private function choice(mixed$v,array$a,string$e):string{if(!is_string($v)||!in_array($v,$a,true))throw new RegulatoryCaseException($e);return$v;}private function text(mixed$v,int$m,string$e):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new RegulatoryCaseException($e);return$v;}private function json(mixed$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
